  "query": {
    "bool": {
      "must": [
        {
          "match": {
            "level": "INFO"
          }
        },
        {
          "range": {
            "duration_ms": {
              "gte": 300
            }
          }
        }
      ]
    }
  },
  "aggs": {
    "endpoints": {
      "terms": {
        "field": "message.keyword",
        "size": 100
      }
    }
  }
}
```

##### Loki

