<link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/reveal.js/4.4.0/reveal.min.css">
<link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/reveal.js/4.4.0/theme/black.min.css">
<style>
    .quiz-question {
        font-size: 24px;
        margin-bottom: 20px;
    }
    .quiz-option {
        font-size: 18px;
        margin-bottom: 10px;
        cursor: pointer;
    }
    .quiz-result {
        font-size: 24px;
        margin-top: 20px;
    }
</style>
</head>
<body>
<div class="reveal">
    <div class="slides">
        <!-- Quiz Slide -->
        <section>
            <h2>Quiz</h2>
            <div id="quiz-container"></div>
        </section>
    </div>
</div>

<script src="https://cdnjs.cloudflare.com/ajax/libs/reveal.js/4.4.0/reveal.min.js"></script>
<script>
// Define the quiz questions and options
const quizQuestions = [
    {
        question: 'What is the capital of France?',
        options: ['Paris', 'London', 'Berlin'],
        correctAnswer: 'Paris'
    },
    {
        question: 'What is the largest planet in our solar system?',
        options: ['Earth', 'Saturn', 'Jupiter'],
        correctAnswer: 'Jupiter'
    }
];

// Initialize the quiz
let currentQuestion = 0;
let score = 0;

// Function to display the current question
function displayQuestion() {
    const quizContainer = document.getElementById('quiz-container');
    quizContainer.innerHTML = ''; // Clear previous content

    const currentQuestionObj = quizQuestions[currentQuestion];
    const questionElement = document.createElement('div');
    questionElement.className = 'quiz-question';
    questionElement.textContent = currentQuestionObj.question;
    quizContainer.appendChild(questionElement);

    currentQuestionObj.options.forEach(option => {
        const optionElement = document.createElement('div');
        optionElement.className = 'quiz-option';
        optionElement.textContent = option;
        optionElement.addEventListener('click', () => checkAnswer(option));
        quizContainer.appendChild(optionElement);
    });
}

// Function to check the answer
function checkAnswer(answer) {
    const currentQuestionObj = quizQuestions[currentQuestion];
    if (answer === currentQuestionObj.correctAnswer) {
        score++;
    }

    currentQuestion++;
    if (currentQuestion < quizQuestions.length) {
        displayQuestion();
    } else {
        displayResults();
    }
}

// Function to display the results
function displayResults() {
    const quizContainer = document.getElementById('quiz-container');
    quizContainer.innerHTML = ''; // Clear previous content

    const resultElement = document.createElement('div');
    resultElement.className = 'quiz-result';
    resultElement.textContent = `Your score: ${score}/${quizQuestions.length}`;
    quizContainer.appendChild(resultElement);
}

// Initialize the quiz
displayQuestion();

// Initialize Reveal.js
Reveal.initialize({
    controls: true,
    progress: true,
    history: true,
    center: true,
    hash: true
});
</script>
</body>
</html>
```

### Explanation

1. **HTML Structure:**
   - The HTML structure includes a single slide with a `div` element (`#quiz-container`) where the quiz questions and options will be displayed.

2. **JavaScript Logic:**
   - **Quiz Questions:** Defined as an array of objects containing the question, options, and correct answer.
   - **Display Question:** Clears the previous content and displays the current question and its options.
   - **Check Answer:** Checks if the selected answer is correct and updates the score. Moves to the next question or displays the results if all questions are answered.
   - **Display Results:** Displays the final score once all questions are answered.

3. **Styling:**
   - Basic CSS styles are applied to the quiz elements for better visibility.

4. **Reveal.js Initialization:**
   - Initializes Reveal.js with basic configuration options.

### Customization

- **Add More Questions:** You can easily add more questions to the `quizQuestions` array.
- **Customize Styling:** Modify the CSS styles to fit your presentation design.
- **Enhance Interactivity:** Add more interactivity, such as highlighting correct/incorrect answers, or providing feedback after each question.

By following this approach, you can implement an interactive quiz feature in your Reveal.js presentation to increase engagement and provide immediate feedback to your audience.

