  try {
    await new Promise(resolve => setTimeout(resolve, 10)); // Simulate async operation
    Reveal.slide(slideIndex);
    console.log(`Loaded slide ${slideIndex}`);
  } catch (error) {
    console.error(`Failed to load slide ${slideIndex}: ${error}`);
  }
}

// Preload slides in batches
async function preloadSlides(totalSlides, batchSize = 10) {
  for (let i = 0; i < totalSlides; i += batchSize) {
    const batch = [];
    for (let j = i; j < i + batchSize && j < totalSlides; j++) {
      batch.push(loadSlide(j));
    }
    await Promise.all(batch); // Wait for all slides in the batch to load
  }
}

