import com.atlassian.jira.rest.client.api.JiraRestClient;
import com.atlassian.jira.rest.client.api.domain.input.FieldInput;
import com.atlassian.jira.rest.client.api.domain.input.IssueInput;
import com.atlassian.jira.rest.client.api.domain.input.UpdateIssueInput;
import com.atlassian.jira.rest.client.api.domain.input.FieldInputBuilder;
import com.atlassian.jira.rest.client.api.domain.input.IssueInputBuilder;
import com.atlassian.jira.rest.client.api.domain.input.UpdateIssueInputBuilder;
import com.atlassian.jira.rest.client.api.JiraRestClientFactory;
import com.atlassian.util.concurrent.Promise;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class JiraUpdater {

    private static final int THREAD_POOL_SIZE = 10; // Adjust based on your environment
    private static final int BATCH_SIZE = 10; // Adjust based on your environment

    public static void main(String[] args) {
        ExecutorService executorService = Executors.newFixedThreadPool(THREAD_POOL_SIZE);
        JiraRestClientFactory factory = new AsynchronousJiraRestClientFactory();
        JiraRestClient client = factory.createWithBasicHttpAuthentication(
                "https://example.atlassian.net",
                "username",
                "password");

        List<String> issueKeys = List.of("ISSUE-123", "ISSUE-124", "ISSUE-125"); // Example list of issue keys

        for (int i = 0; i < issueKeys.size(); i += BATCH_SIZE) {
            int endIndex = Math.min(i + BATCH_SIZE, issueKeys.size());
            List<String> batch = issueKeys.subList(i, endIndex);

            for (String issueKey : batch) {
                executorService.submit(() -> updateIssue(client, issueKey));
            }

            try {
                TimeUnit.MILLISECONDS.sleep(100); // Throttle to avoid hitting rate limits
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }

        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
            Thread.currentThread().interrupt();
        }
    }

    private static void updateIssue(JiraRestClient client, String issueKey) {
        Promise<IssueInput> issuePromise = client.getIssueClient().getIssue(issueKey);
        IssueInput issue = issuePromise.claim();

        FieldInput summaryField = FieldInputBuilder.builder()
                .fieldId("summary")
                .value("New summary")
                .build();

        FieldInput descriptionField = FieldInputBuilder.builder()
                .fieldId("description")
                .value("New description")
                .build();

        UpdateIssueInput updateInput = UpdateIssueInputBuilder.builder()
                .fields(List.of(summaryField, descriptionField))
                .build();

        try {
            client.getIssueClient().updateIssue(issue.getId(), updateInput).claim();
        } catch (Exception e) {
            System.err.println("Failed to update issue " + issueKey + ": " + e.getMessage());
        }
    }
}
```

### Explanation

1. **ExecutorService**: Uses a fixed thread pool to manage concurrent updates.
2. **Batches**: Issues are processed in batches to reduce the number of API calls.
3. **Throttling**: Sleeps briefly between batches to avoid hitting rate limits.
4. **Error Handling**: Implements error handling to catch and log exceptions.
5. **Update Issue**: Uses `UpdateIssueInput` to update specific fields rather than the entire issue.

