import java.io.IOException;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.Duration;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutionException;
import java.util.logging.Level;
import java.util.logging.Logger;
import com.google.common.cache.CacheBuilder;
import com.google.common.cache.CacheLoader;
import com.google.common.cache.LoadingCache;

public class Main {
    private static final Logger LOGGER = Logger.getLogger(Main.class.getName());
    private static final HttpClient CLIENT = HttpClient.newHttpClient();
    private static final String API_URL = "https://api.example.com/data";
    private static final int MAX_CACHE_SIZE = 100;
    private static final Duration CACHE_EXPIRY_DURATION = Duration.ofMinutes(10);

    private static final LoadingCache<String, String> cache = CacheBuilder.newBuilder()
            .maximumSize(MAX_CACHE_SIZE)
            .expireAfterWrite(CACHE_EXPIRY_DURATION)
            .build(new CacheLoader<>() {
                @Override
                public String load(String key) throws Exception {
                    return fetchExternalApiData(key).join();
                }
            });

    public static void main(String[] args) {
        // Example usage
        CompletableFuture<String> responseFuture = fetchCachedData(API_URL);
        try {
            String response = responseFuture.join();
            System.out.println(response);
        } catch (ExecutionException | InterruptedException e) {
            LOGGER.log(Level.SEVERE, "Failed to fetch data from external API", e);
        }
    }

    public static CompletableFuture<String> fetchCachedData(String apiUrl) {
        return CompletableFuture.supplyAsync(() -> {
            try {
                return cache.get(apiUrl);
            } catch (Exception e) {
                throw new RuntimeException("Failed to fetch data from cache", e);
            }
        });
    }

    public static CompletableFuture<String> fetchExternalApiData(String apiUrl) {
        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(apiUrl))
                .build();

        return CompletableFuture.supplyAsync(() -> {
            try {
                HttpResponse<String> response = CLIENT.send(request, HttpResponse.BodyHandlers.ofString());
                if (response.statusCode() ==  200) {
                    return response.body();
                } else {
                    throw new RuntimeException("Unexpected response status code: " + response.statusCode());
                }
            } catch (IOException | InterruptedException e) {
                throw new RuntimeException("Failed to fetch data from external API", e);
            }
        }).exceptionally(t -> {
            // Retry logic with exponential backoff
            int maxRetries = 3;
            int retryCount = 0;
            while (retryCount < maxRetries) {
                try {
                    Thread.sleep(Duration.ofSeconds((long) Math.pow(2, retryCount)).toMillis());
                    return fetchExternalApiData(apiUrl).join();
                } catch (Exception ex) {
                    retryCount++;
                }
            }
            throw new RuntimeException("Failed to fetch data from external API after retries", t);
        });
    }
}
```

### Explanation

1. **Caching**:
   - We use Guava's `LoadingCache` to cache the responses from the external API.
   - The cache has a maximum size of 100 entries and expires entries after 10 minutes.
   - The `load` method of the `CacheLoader` fetches data from the external API and populates the cache.

2. **Concurrency**:
   - The `fetchCachedData` method retrieves data from the cache asynchronously using `CompletableFuture.supplyAsync`.

3. **Retry Logic**:
   - The `fetchExternalApiData` method includes a retry mechanism with exponential backoff.
   - It attempts to fetch data up to 3 times, waiting for an exponentially increasing duration between retries (1, 2, 4 seconds).

