```java
import java.util.concurrent.TimeUnit;

public class JiraSync {

    private static final int MAX_RETRIES = 3;
    private static final long RETRY_DELAY_MS = 1000;

    public static void main(String[] args) {
        // Set up Jira connection
        Jira jira = new Jira(JIRA_URL, JIRA_USERNAME, JIRA_PASSWORD);

        // Set up Confluence connection
        Confluence confluence = new Confluence(CONFLUENCE_URL, CONFLUENCE_USERNAME, CONFLUENCE_PASSWORD);

        // Try to sync tickets
        try {
            IssueService issueService = jira.getIssueService();
            List<Issue> issues = issueService.getIssues(JqlQuery.parse("project = " + PROJECT_KEY));
            for (Issue issue : issues) {
                logger.info("Syncing issue: {}", issue.getKey());

                boolean success = false;
                int retries = 0;
                while (!success && retries < MAX_RETRIES) {
                    try {
                        // Create a new Confluence page for each issue
                        Page page = confluence.createPage(
                                SPACE_KEY,
                                issue.getSummary(),
                                issue.getDescription()
                        );

                        // Link the Confluence page to the Jira issue
                        confluence.linkPage(page.getId(), issue.getId());

                        success = true;
                        logger.info("Successfully synced issue: {}", issue.getKey());
                    } catch (Exception e) {
                        retries++;
                        logger.warn("Failed to sync issue {}: Attempt {} of {}. Retrying...", issue.getKey(), retries, MAX_RETRIES);
                        TimeUnit.MILLISECONDS.sleep(RETRY_DELAY_MS);
                    }
                }

                if (!success) {
                    logger.error("Failed to sync issue {} after {} attempts.", issue.getKey(), MAX_RETRIES);
                }
            }
        } catch (Exception e) {
            logger.error("Error syncing tickets: {}", e.getMessage());
        }
    }
}
```

