import java.util.HashMap;
import java.util.Map;

public class PriorityAnalyzer {
    private Map<String, Integer> usageCounts;
    private Map<String, Integer> feedbackScores;

    public PriorityAnalyzer() {
        this.usageCounts = new HashMap<>();
        this.feedbackScores = new HashMap<>();
    }

    public void updateUsageCount(ScreenField screenField) {
        String id = screenField.getId();
        usageCounts.merge(id, 1, Integer::sum);
    }

    public void updateFeedbackScore(ScreenField screenField, int score) {
        String id = screenField.getId();
        feedbackScores.put(id, score);
    }

    public void calculatePriorities() {
        for (String id : usageCounts.keySet()) {
            int usageCount = usageCounts.get(id);
            int feedbackScore = feedbackScores.getOrDefault(id, 0);
            int priority = calculatePriority(usageCount, feedbackScore);
            updatePriority(id, priority);
        }
    }

    private int calculatePriority(int usageCount, int feedbackScore) {
