import java.util.List;

public class EpicLinkFixer {

    private IssueLinkManager issueLinkManager;
    private JiraAuthenticationContext authenticationContext;

    public EpicLinkFixer() {
        this.issueLinkManager = ComponentAccessor.getIssueLinkManager();
        this.authenticationContext = ComponentAccessor.getJiraAuthenticationContext();
    }

    public List<IssueLink> findBrokenEpicLinks() {
        ApplicationUser user = authenticationContext.getLoggedInUser();
        List<Project> projects = ComponentAccessor.getProjectManager().getProjects(user);

        List<IssueLink> brokenLinks = issueLinkManager.getAllIssueLinks()
                .stream()
                .filter(link -> link.getIssueLinkType().getName().equals("Epic-Story Link"))
                .filter(link -> isLinkBroken(link))
                .toList();

        return brokenLinks;
    }

    private boolean isLinkBroken(IssueLink link) {
        Issue sourceIssue = link.getSourceIssueObject();
        Issue destinationIssue = link.getDestinationIssueObject();
        return sourceIssue == null || destinationIssue == null || !sourceIssue.exists() || !destinationIssue.exists();
    }
}
