    Issue destinationIssue = ComponentAccessor.getIssueManager().getIssueObject(destinationIssueId);

    if (sourceIssue == null || destinationIssue == null) {
        throw new IllegalArgumentException("One or both issues do not exist.");
    }

    if (!hasPermissionToCreateLink(sourceIssue)) {
