        Issue sourceIssue = ComponentAccessor.getIssueManager().getIssueObject(sourceIssueId);
        Issue destinationIssue = ComponentAccessor.getIssueManager().getIssueObject(destinationIssueId);

        if (sourceIssue == null || destinationIssue == null) {
            throw new IllegalArgumentException("One or both issues do not exist.");
        }

        if (!hasPermissionToCreateLink(sourceIssue)) {
            LOGGER.warn("User {} attempted to create an epic link but lacks the necessary permissions.", authenticationContext.getLoggedInUser().getUsername());
            throw new SecurityException("User does not have permission to create links.");
        }

        // Proceed with creating the link
        ComponentAccessor.getIssueLinkManager().createIssueLink(
            sourceIssueId,
            destinationIssueId,
            ComponentAccessor.getIssueLinkTypeManager().getIssueLinkTypeByName("Epic-Story Link").getId(),
            true
        );

        LOGGER.info("User {} successfully created an epic link between issues {} and {}", 
            authenticationContext.getLoggedInUser().getUsername(), sourceIssue.getKey(), destinationIssue.getKey());
    }
}
